const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const now = Date.now();
// чистимо журнал: записи, старші за 72 години
for (const [link, ts] of Object.entries(staticData.seen)) {
  if (now - ts > 72 * 3600 * 1000) delete staticData.seen[link];
}
const fresh = [];
for (const item of $input.all()) {
  const link = item.json.link || item.json.guid || '';
  if (!link || staticData.seen[link]) continue; // дубль — пропускаємо
  staticData.seen[link] = now;
  const title = (item.json.title || '').trim();
  fresh.push({
    json: {
      title,
      link,
      card: '📰 ' + title + '\n' + link + '\n\n✅ Беремо в роботу → перешліть у чат «В роботі»\n❌ Не беремо → просто ігноруйте'
    }
  });
}
return fresh;
